$key = "race-test-" + [guid]::NewGuid().ToString(); Write-Host "Using idempotency key: $key"; $jobs = 1..10 | ForEach-Object { Start-Job -ScriptBlock { param($key) try { $response = Invoke-WebRequest -Uri "http://localhost:8080/api/v1/payments" -Method POST -Headers @{ "Idempotency-Key" = $key; "Content-Type" = "application/json" } -Body '{"amount": 500.00, "currency": "INR", "paymentMethod": "UPI"}' -UseBasicParsing; "$($response.StatusCode) | id=$(($response.Content | ConvertFrom-Json).id)" } catch { "ERROR: $($_.Exception.Message)" } } -ArgumentList $key }; $jobs | Wait-Job | Receive-Job; $jobs | Remove-Job